ee:message.ee:set-payload:
%dw 2.0
output application/json
var message = vars.amqConfig.transaction match {
				case "RTO" -> "Returned all messages to source queue: " ++ (vars.amqConfig.queueName default "")
				case "TMQ" -> "Published all messages from " ++ (vars.amqConfig.sourceQueue default "") ++ " to " ++ (vars.amqConfig.targetQueue default "")
			}
---
{
	"message": message
}

%dw 2.0
output application/json
---
{
	"message": "No messages available to publish to source queue"
}

%dw 2.0
output application/json
var message = vars.amqConfig.transaction match {
				case "RTO" -> "Returned message/s '" ++ ((vars.osAttributes.messageIdList default []) joinBy ", ") ++ "' to source queue: " ++ (vars.amqConfig.queueName default "")
				case "TMQ" -> "Published message/s '" ++ ((vars.osAttributes.messageIdList default []) joinBy ", ") ++ "' from " ++ (vars.amqConfig.sourceQueue default "") ++ " to " ++ (vars.amqConfig.targetQueue default "")
			}
---
{
	"message": message
}

%dw 2.0
output application/json
---
{
	"message": "Either provide messageId or set returnAllMessages to true"
}
